using System;using System.Collections.Generic;using System.Linq;using HarmonyLib;using RimWorld;using UnityEngine;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static class HellCombat {
  public const float BeamRadius=10;public const int BeamWarningTicks=45,BeamImpactTicks=18,BeamDischargeTicks=90;
  public static readonly string[] Descriptions={"Launch an eighteen-cell hellfire crescent in the aimed direction through a clear three-cell lane. Builds up to three owned Hellbrands; at most 24 enemies once.","Dash up to sixteen checked cells into a free melee landing, leaving a sharp ember wake and fitted afterimages.","Spin an eight-cell crown of burning sword sweeps. Each of at most twenty enemies is struck once.","Approach, rise, mark a visible warning and descend as a ruinous phoenix. Consume Hellbrands for a capped focused strike and a five-cell burst.","Requires two or more enemies within three cells. Leap up to five cells away, then rush back through the enemy line. Walls and occupied landings block unsafe routes; each enemy once.","Stab Ashreign into the ground. After a short warning, an eight-cell furnace shockwave damages, staggers and safely pushes enemies outward. No spawned walls or permanent terrain.","Mark a fixed location within twenty-eight cells. After a 0.75-second warning, twisting furnace flames collapse into a ten-cell explosion. Up to 32 enemies receive one committed strike; Hellbrands amplify that same hit. The remaining column is visual only."};
  public static bool Enemy(Pawn p,Pawn t){return IncarnateCombat.Enemy(p,t);}
  public static List<Pawn> Targets(Pawn p,IntVec3 at,float radius,int cap){return IncarnateCombat.Targets(p,at,radius,cap);}
  public static bool Route(Pawn p,IntVec3 a,IntVec3 b,Pawn target){if(!IncarnateCombat.Route(p,a,b,target))return false;var prior=a;foreach(var cell in LightningGeometry.Trace(a,b)){var door=cell.GetEdifice(p.Map) as Building_Door;if(door!=null&&!door.Open)return false;int dx=cell.x-prior.x,dz=cell.z-prior.z;if(dx!=0&&dz!=0&&(!LightningCombat.Open(new IntVec3(prior.x+dx,0,prior.z),p.Map)||!LightningCombat.Open(new IntVec3(prior.x,0,prior.z+dz),p.Map)))return false;prior=cell;}return true;}
  static bool Landing(Pawn p,IntVec3 from,Pawn target,float range,out IntVec3 end){end=IntVec3.Invalid;return Enemy(p,target)&&ThunderstormBlitz.ChooseLanding(from,target.Position,range,c=>ThunderstormBlitz.Landing(p,c),(a,b)=>Route(p,a,b,target),out end);}
  public static Job Plan(Pawn p,int n,LocalTargetInfo target,bool automatic){
   if(!p.Spawned||!target.IsValid||!target.Cell.InBounds(p.Map)||target.Cell.Fogged(p.Map)||p.Position.DistanceToSquared(target.Cell)>HellFlameIncarnate.Ranges[n]*HellFlameIncarnate.Ranges[n])return null;
   IntVec3 retreat=IntVec3.Invalid,end=IntVec3.Invalid;
   if(n==0){if(target.Cell==p.Position||!LightningCombat.ClearLine(p.Position,target.Cell,p.Map))return null;}
   else if(n==2||n==5){if(Targets(p,p.Position,8,1).Count==0)return null;target=p;}
   else if(n==4){var threats=Targets(p,p.Position,3,16);if(threats.Count<2)return null;target=threats[0];int before=threats.Min(t=>p.Position.DistanceToSquared(t.Position));float best=-1;
    foreach(var cell in GenRadial.RadialCellsAround(p.Position,5,false)){if(p.Position.DistanceToSquared(cell)<9||!ThunderstormBlitz.Landing(p,cell)||!Route(p,p.Position,cell,null))continue;int separation=threats.Min(t=>cell.DistanceToSquared(t.Position));IntVec3 landing;if(separation<=before||separation<9||!Landing(p,cell,target.Pawn,16,out landing))continue;float score=separation-.1f*p.Position.DistanceToSquared(cell);if(score>best){best=score;retreat=cell;end=landing;}}
    if(!retreat.IsValid)return null;
   }else if(n==6){if(!LightningCombat.Open(target.Cell,p.Map)||!LightningCombat.ClearLine(p.Position,target.Cell,p.Map))return null;end=target.Cell;}
   else if(!Landing(p,p.Position,target.Pawn,HellFlameIncarnate.Ranges[n],out end))return null;
   var job=JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed(HellFlameIncarnate.CombatJob),target,retreat,end);job.count=n;job.playerForced=!automatic;return job;
  }
 }
 public sealed class HediffCompProperties_Hellbrand:HediffCompProperties{public HediffCompProperties_Hellbrand(){compClass=typeof(HediffComp_Hellbrand);}}
 public sealed class HediffComp_Hellbrand:HediffComp {
  public Pawn owner;public int stacks,expires;
  public override bool CompShouldRemove{get{return stacks<=0||owner==null||owner.Dead||Find.TickManager.TicksGame>=expires||Pawn.Dead;}}
  public override void CompExposeData(){Scribe_References.Look(ref owner,"hellbrandOwner");Scribe_Values.Look(ref stacks,"hellbrandStacks");Scribe_Values.Look(ref expires,"hellbrandExpires");}
  public override string CompLabelInBracketsExtra{get{return stacks+" / 3";}}
 }
 public static class HellBrands {
  static HediffComp_Hellbrand Owned(Pawn source,Pawn target){return target==null||target.health==null?null:target.health.hediffSet.hediffs.Select(h=>h.TryGetComp<HediffComp_Hellbrand>()).FirstOrDefault(c=>c!=null&&c.owner==source&&!c.CompShouldRemove);}
  public static int Count(Pawn source,Pawn target){var c=Owned(source,target);return c==null?0:Math.Min(3,c.stacks);}
  public static void Apply(Pawn source,Pawn target){if(!HellCombat.Enemy(source,target))return;var c=Owned(source,target);if(c==null){if(target.health.hediffSet.hediffs.Count(item=>item.def.defName=="EH_Hellbrand")>=8)return;var h=(HediffWithComps)HediffMaker.MakeHediff(DefDatabase<HediffDef>.GetNamed("EH_Hellbrand"),target);c=h.TryGetComp<HediffComp_Hellbrand>();c.owner=source;c.stacks=1;c.expires=Find.TickManager.TicksGame+600;target.health.AddHediff(h);}else{c.stacks=Math.Min(3,c.stacks+1);c.expires=Find.TickManager.TicksGame+600;}HellVfx.Burst(source,10,target.DrawPos,1.8f,24);}
  public static int Consume(Pawn source,Pawn target){var c=Owned(source,target);if(c==null)return 0;int count=Math.Min(3,c.stacks);c.stacks=0;target.health.RemoveHediff(c.parent);return count;}
 }
 public sealed class JobDriver_HellTechnique:JobDriver {
  public int phase,ticks,elapsed,duration,leg;IntVec3 start,impactCell,rushStart;bool initialized,moving,committed;public bool impacting;HashSet<int> struck=new HashSet<int>();
  public int Skill{get{return job.count;}}int Power{get{return job.count;}}Pawn Target{get{return job.targetA.Pawn;}}IntVec3 Destination{get{return Power==4&&leg==0?job.targetB.Cell:job.targetC.Cell;}}
  public Vector3 VisualAt{get{return moving?Vector3.Lerp(start.ToVector3Shifted(),Destination.ToVector3Shifted(),Mathf.SmoothStep(0,1,elapsed/(float)Math.Max(1,duration))):pawn.Position.ToVector3Shifted();}}
  public float Lift{get{return (Power==4&&leg==0&&moving)?1.2f*Mathf.Sin(Mathf.Clamp01(elapsed/(float)Math.Max(1,duration))*Mathf.PI):Power==3&&phase==2?.8f*Mathf.Sin(Mathf.Clamp01(ticks/14f)*Mathf.PI):0;}}
  public override bool TryMakePreToilReservations(bool errorOnFailed){return true;}
  public override void ExposeData(){base.ExposeData();Scribe_Values.Look(ref phase,"hellPhase");Scribe_Values.Look(ref ticks,"hellTicks");Scribe_Values.Look(ref elapsed,"hellElapsed");Scribe_Values.Look(ref duration,"hellDuration");Scribe_Values.Look(ref leg,"hellLeg");Scribe_Values.Look(ref start,"hellStart");Scribe_Values.Look(ref rushStart,"hellRushStart");Scribe_Values.Look(ref impactCell,"hellImpactCell");Scribe_Values.Look(ref initialized,"hellInitialized");Scribe_Values.Look(ref moving,"hellMoving");Scribe_Values.Look(ref committed,"hellCommitted");Scribe_Collections.Look(ref struck,"hellStruck",LookMode.Value);if(struck==null)struck=new HashSet<int>();}
  bool Valid(){return HellFlameIncarnate.Active(pawn)&&HediffComp_ElementalTransform.Active(pawn)&&ElementalTeaching.Ready(pawn)&&!pawn.WorkTagIsDisabled(WorkTags.Violent)&&(!ElementalCombatPolicy.Controlled(pawn)||pawn.Drafted)&&!ElementalAnimationBridge.ExternallyControlled(pawn);}
  void MoveStart(){start=pawn.Position;if(Power==4&&leg==1)rushStart=start;elapsed=0;duration=Math.Max(6,Math.Min(14,(int)Math.Ceiling(start.DistanceTo(Destination)*.65f)+4));moving=true;phase=1;ticks=0;pawn.Rotation=Rot4.FromAngleFlat((Destination-start).ToVector3().AngleFlat());ElementalAudio.Ability(pawn,ElementalSound.Dash);}
  void Finish(){moving=false;impacting=false;if(!pawn.Spawned||pawn.Dead||pawn.Downed||ElementalAnimationBridge.ExternallyControlled(pawn)||ThunderstormBlitz.Landing(pawn,pawn.Position))return;foreach(var cell in GenRadial.RadialCellsAround(pawn.Position,1.5f,false))if(ThunderstormBlitz.Landing(pawn,cell)&&HellCombat.Route(pawn,pawn.Position,cell,null)){ThunderstormBlitz.Move(pawn,cell);return;}}
  void Hit(Pawn target,float physical,float thermal,bool brand,bool consume=false,bool push=false){if(!Valid()||!HellCombat.Enemy(pawn,target)||!struck.Add(target.thingIDNumber))return;var profile=FlameCombat.Profile(pawn,10);profile.penetration+=.3f;int marks=consume?HellBrands.Consume(pawn,target):0;if(marks>=3){profile.damage*=1.2f;HediffComp_HellFlameIncarnate.On(pawn).wardUntil=Find.TickManager.TicksGame+120;}bool hit=FlameCombat.Strike(pawn,target,profile,physical,thermal+marks*.4f,true);if(hit&&brand&&!target.Dead)HellBrands.Apply(pawn,target);if(!target.Dead&&target.Spawned&&!target.Downed){if(push)CelestialCombat.Push(pawn,target,3);if(push)target.stances.stagger.StaggerFor(90);}}
  void Impact(){if(committed)return;committed=true;impacting=true;try{ElementalAudio.Ability(pawn,Power==0?ElementalSound.Slash:Power==2?ElementalSound.Spin:ElementalSound.Impact);
   if(Power==0){var direction=(job.targetA.Cell-pawn.Position).ToVector3();direction.Normalize();var end=(pawn.Position.ToVector3Shifted()+direction*18).ToIntVec3();var last=pawn.Position;foreach(var c in LightningGeometry.Trace(pawn.Position,end)){if(!c.InBounds(pawn.Map)||!LightningCombat.Open(c,pawn.Map)||pawn.Position.DistanceToSquared(c)>324)break;last=c;}float length=pawn.Position.DistanceTo(last);foreach(var target in HellCombat.Targets(pawn,pawn.Position,18,32)){var offset=(target.Position-pawn.Position).ToVector3();float along=Vector3.Dot(offset,direction),across=Mathf.Abs(offset.x*direction.z-offset.z*direction.x);if(along<0||along>length+.5f||across>1.5f||struck.Count>=24)continue;Hit(target,1.6f,1.5f,true);}HellVfx.Wave(pawn,0,pawn.DrawPos,last.ToVector3Shifted(),28,5);}
   else if(Power==1){if(HellCombat.Enemy(pawn,Target)&&pawn.Position.DistanceToSquared(Target.Position)<=2){Hit(Target,1.8f,1.8f,true);HellVfx.Burst(pawn,15,Target.DrawPos,4,24);}}
   else if(Power==2){foreach(var target in HellCombat.Targets(pawn,pawn.Position,8,20))Hit(target,1.6f,1.8f,true);HellVfx.Burst(pawn,2,pawn.DrawPos,26,38);}
   else if(Power==3){if(HellCombat.Enemy(pawn,Target)&&pawn.Position.DistanceToSquared(Target.Position)<=2){var at=Target.Position;var others=HellCombat.Targets(pawn,at,5,24);Hit(Target,6f,4.4f,false,true);foreach(var target in others)if(target!=Target)Hit(target,1.5f,1.8f,false);HellVfx.Burst(pawn,4,at.ToVector3Shifted(),13,38);HellVfx.Burst(pawn,7,at.ToVector3Shifted(),16,32);}}
   else if(Power==4){Vector3 a=rushStart.ToVector3Shifted(),b=pawn.Position.ToVector3Shifted(),direction=b-a;float length=direction.magnitude;if(length>.01f)direction/=length;foreach(var target in HellCombat.Targets(pawn,rushStart,18,24)){var offset=target.Position.ToVector3Shifted()-a;float along=Vector3.Dot(offset,direction),across=Mathf.Abs(offset.x*direction.z-offset.z*direction.x);if(along>=-1&&along<=length+1.5f&&across<=1.5f&&LightningCombat.ClearLine(pawn.Position,target.Position,pawn.Map))Hit(target,2.2f,2.2f,true);}HellVfx.Line(pawn,1,a,b,26,2);}
   else if(Power==5){foreach(var target in HellCombat.Targets(pawn,pawn.Position,8,24))Hit(target,3.8f,3.2f,false,false,true);HellVfx.Burst(pawn,12,pawn.DrawPos,26,48);}
   else if(Power==6){foreach(var target in HellCombat.Targets(pawn,impactCell,10,32))Hit(target,2f,5.8f,false,true);HellVfx.Burst(pawn,7,impactCell.ToVector3Shifted(),32,54);}
  }finally{impacting=false;}}
  void BeamVisual(){var at=impactCell.ToVector3Shifted();if(phase==0)HellVfx.BeamWarning(pawn,at,Math.Max(1,45-ticks));else if(phase==4)HellVfx.Beam(pawn,at,ticks);}
  protected override IEnumerable<Toil> MakeNewToils(){AddFinishAction(c=>Finish());this.FailOn(()=>!Valid());var form=new Toil{defaultCompleteMode=ToilCompleteMode.Never,handlingFacing=true};
   form.initAction=()=>{pawn.pather.StopDead();pawn.stances.CancelBusyStanceHard();HellVfx.Track(pawn);if(initialized){if(Power==6)BeamVisual();return;}initialized=true;start=pawn.Position;impactCell=job.targetA.Cell;phase=0;ticks=0;ElementalAudio.Ability(pawn,Power>=3?ElementalSound.Charge:ElementalSound.Slash);if(Power==6)BeamVisual();if(Power==1||Power==3||Power==4){if(Power==4)HellVfx.Burst(pawn,5,pawn.DrawPos,4,25);MoveStart();}};
   form.tickAction=()=>{pawn.pather.StopDead();ticks++;
    if(Power==6){if(phase==0){if(!impactCell.InBounds(pawn.Map)||!LightningCombat.Open(impactCell,pawn.Map)){EndJobWith(JobCondition.Incompletable);return;}if(ticks<45)return;phase=4;ticks=0;BeamVisual();return;}if(phase==4){if(ticks>=18&&!committed)Impact();if(ticks>=90){phase=3;ticks=0;}return;}if(phase==3&&ticks>=8)ReadyForNextToil();return;}
    if(phase==0){if(ticks<(Power==5?20:Power==2?8:5))return;Impact();phase=3;ticks=0;return;}
    if(phase==1){if(!Destination.IsValid||!ThunderstormBlitz.Landing(pawn,Destination)){EndJobWith(JobCondition.Incompletable);return;}var from=VisualAt;int next=Math.Min(duration,elapsed+1);var to=Vector3.Lerp(start.ToVector3Shifted(),Destination.ToVector3Shifted(),Mathf.SmoothStep(0,1,next/(float)duration));if(!HellCombat.Route(pawn,pawn.Position,to.ToIntVec3(),Power==4&&leg==0?null:Target)){EndJobWith(JobCondition.Incompletable);return;}HellVfx.Line(pawn,1,from,to,20,1.5f);if(elapsed%2==0)HellVfx.Echo(pawn,from);ThunderstormBlitz.Move(pawn,to.ToIntVec3());elapsed=next;if(elapsed<duration)return;moving=false;ThunderstormBlitz.Move(pawn,Destination);if(Power==4&&leg==0){leg=1;MoveStart();return;}if(Power==3){phase=2;ticks=0;HellVfx.Burst(pawn,3,pawn.DrawPos,8,14);return;}Impact();phase=3;ticks=0;return;}
    if(phase==2){if(!HellCombat.Enemy(pawn,Target)||pawn.Position.DistanceToSquared(Target.Position)>2){EndJobWith(JobCondition.Incompletable);return;}if(ticks<14)return;Impact();phase=3;ticks=0;return;}if(phase==3&&ticks>=8)ReadyForNextToil();
   };yield return form;
  }
 }
 [HarmonyPatch(typeof(Pawn_DrawTracker),"get_DrawPos")]
 public static class HellDrawPosition {public static void Postfix(Pawn ___pawn,ref Vector3 __result){var driver=___pawn.jobs==null?null:___pawn.jobs.curDriver as JobDriver_HellTechnique;if(driver==null)return;var at=driver.VisualAt;at.y=__result.y;at.z+=driver.Lift;__result=at;}}
}
